@import "@fontsource-variable/hanken-grotesk";

/* Light (faithful): page #F7F5F2, text #292827, raised #F2F0EB, stone #DEDBD5, brand purple #714CB6,
   lilac #D4C7FF, pale lilac #E8E0FF. chart-1…5 = the deep fields: teal #0C4243, maroon #421D24,
   indigo #281647, purple #714CB6, ink #141413. Dark is the same system on a warm near-black. */
:root {
  --background: oklch(0.971 0.005 78);
  --foreground: oklch(0.278 0.002 68);
  --card: oklch(0.955 0.007 89);
  --card-foreground: oklch(0.278 0.002 68);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.278 0.002 68);
  --primary: oklch(0.511 0.161 296);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.859 0.078 295);
  --secondary-foreground: oklch(0.278 0.002 68);
  --muted: oklch(0.892 0.009 85);
  --muted-foreground: oklch(0.524 0.006 95);
  --accent: oklch(0.922 0.043 297);
  --accent-foreground: oklch(0.278 0.002 68);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.524 0.006 95 / 20%);
  --input: oklch(0.524 0.006 95 / 30%);
  --ring: oklch(0.511 0.161 296 / 50%);
  --highlight: oklch(0.766 0.121 299);
  --highlight-foreground: oklch(0.278 0.002 68);
  --glow: oklch(0.687 0.113 297);
  --chart-1: oklch(0.346 0.053 197);
  --chart-2: oklch(0.286 0.058 9);
  --chart-3: oklch(0.255 0.088 297);
  --chart-4: oklch(0.511 0.161 296);
  --chart-5: oklch(0.191 0.002 107);
  --sidebar: oklch(0.286 0.058 9);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.859 0.078 295);
  --sidebar-primary-foreground: oklch(0.278 0.002 68);
  --sidebar-accent: oklch(1 0 0 / 8%);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 8%);
  --sidebar-ring: oklch(0.859 0.078 295);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 80rem;
  --page-gutter: 1rem;
  --section-y: 6rem;
}

.dark {
  --background: oklch(0.191 0.002 107);
  --foreground: oklch(0.971 0.005 78);
  --card: oklch(0.235 0.003 85);
  --card-foreground: oklch(0.971 0.005 78);
  --popover: oklch(0.223 0.002 68);
  --popover-foreground: oklch(0.971 0.005 78);
  --primary: oklch(0.766 0.121 299);
  --primary-foreground: oklch(0.2 0.01 296);
  --secondary: oklch(0.859 0.078 295);
  --secondary-foreground: oklch(0.2 0.01 296);
  --muted: oklch(0.281 0.004 85);
  --muted-foreground: oklch(0.72 0.006 90);
  --accent: oklch(0.29 0.075 297);
  --accent-foreground: oklch(0.971 0.005 78);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 18%);
  --ring: oklch(0.766 0.121 299 / 55%);
  --highlight: oklch(0.766 0.121 299);
  --highlight-foreground: oklch(0.2 0.01 296);
  --glow: oklch(0.55 0.14 297);
  --chart-1: oklch(0.346 0.053 197);
  --chart-2: oklch(0.286 0.058 9);
  --chart-3: oklch(0.255 0.088 297);
  --chart-4: oklch(0.511 0.161 296);
  --chart-5: oklch(0.15 0.002 107);
  --sidebar: oklch(0.255 0.05 9);
  --sidebar-foreground: oklch(0.971 0.005 78);
  --sidebar-primary: oklch(0.859 0.078 295);
  --sidebar-primary-foreground: oklch(0.2 0.01 296);
  --sidebar-accent: oklch(1 0 0 / 8%);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 8%);
  --sidebar-ring: oklch(0.859 0.078 295);
}
